#!/usr/bin/perl -w
#
# Script to generate module.yaml from module-template.yaml by adding
# autogenerated semconv mount entries. The entries are generated from the list
# of README.md files in the semconv submodules (core and GenAI).
#
# Note that this script might be called in situations where some but not all
# content-modules have been initialized. If the semconv submodule is not
# git-submodule initialized, the script will warn and skip it.
#
# Reads from: $MODULE_CONFIG_TEMPLATE (version-controlled template) Writes to:
# $MODULE_CONFIG_YAML (generated, gitignored)

use strict;
use warnings;
use diagnostics;

# Configuration
my $MODULE_CONFIG_TEMPLATE = "config/_default/module-template.yaml";
my $MODULE_CONFIG_YAML = "config/_default/module.yaml";

# Semconv sets published under the Semantic Conventions section. For each set,
# every docs README.md is mounted as the section's _index.md.
my @SEMCONV_SETS = (
  {
    dir => "content-modules/semantic-conventions",
    tmp => "tmp/semconv/docs",
    target => "content/docs/specs/semconv/core",
  },
  {
    dir => "content-modules/semantic-conventions-genai",
    tmp => "tmp/semconv-genai/docs",
    target => "content/docs/specs/semconv/genai",
    # Not published, see cp-pages.sh
    exclude => qr{^gen-ai/non-normative/tests/},
  },
);

# Marker comments in YAML file to look for
sub markerFor($) {
  my ($qualifier) = @_;
  return "# DO NOT EDIT - semconv autogenerated mounts $qualifier - DO NOT EDIT";
}
my $START_MARKER = markerFor("below");
my $END_MARKER = markerFor("above");

sub main() {
  my @mount_entries = ();
  my $found_sets = 0;

  foreach my $set (@SEMCONV_SETS) {
    my $dir = $set->{dir};
    my $docs_dir = "$dir/docs";

    if (! -e $dir) {
      # The directory should be present even if the submodule isn't initialized.
      print STDERR "ERROR: submodule directory not found: $dir\n";
      exit 1;
    }

    if (! -e "$dir/.git") {
      print STDERR
        "WARNING: submodule not initialized, '.git' directory not found in $dir\n" .
        "         Skipping its semconv mount config generation.\n" .
        "         Run 'npm run get:submodule' to initialize.\n";
      next;
    } else {
      print STDERR "Submodule found and initialized: $dir\n";
    }

    if (! -e $docs_dir) {
      print STDERR "ERROR: directory '$docs_dir' expected but not found.\n";
      exit 1;
    }

    # Find all README.md by running system `find`. Must be in $dir for find to
    # generate the correct relative paths
    my $readme_files = `cd $dir && find docs -name "README.md" | sort`;
    chomp $readme_files;

    die "No README.md files found under $docs_dir\n" unless $readme_files;

    my @entries = generate_mount_entries($set, $readme_files);
    my $file_count = @entries / 2;
    print "Found $file_count README.md files to mount from $docs_dir\n";
    push @mount_entries, @entries;
    $found_sets++;
  }

  if (!$found_sets) {
    print STDERR "WARNING: no semconv submodule initialized; skipping mount config generation.\n";
    exit 0;
  }

  # Generate module.yaml from module-base.yaml
  generate_module_yaml(\@mount_entries);

  print "Successfully generated $MODULE_CONFIG_YAML with semconv mount entries\n";
}

sub generate_mount_entries {
  my ($set, $readme_files) = @_;

  my @mount_entries = ();

  foreach my $path (split(/\n/, $readme_files)) {
    next if $path =~ /^\s*$/;

    $path =~ s|^(./)?docs/||; # strip prefix
    next if $set->{exclude} && $path =~ $set->{exclude};

    my $target = $path;
    $target =~ s/README\.md$/_index.md/;

    push @mount_entries, "  - source: $set->{tmp}/$path\n";
    push @mount_entries, "    target: $set->{target}/$target\n";
  }

  return @mount_entries;
}

sub generate_module_yaml {
  my ($new_mount_entries_ref) = @_;

  # Read the template
  open(my $read_fh, '<', $MODULE_CONFIG_TEMPLATE) or die "Cannot open $MODULE_CONFIG_TEMPLATE: $!\n";
  my @lines = <$read_fh>;
  close($read_fh);

  # Find the start and end markers
  my $start_line = -1;
  my $end_line = -1;

  for (my $i = 0; $i < @lines; $i++) {
    if ($lines[$i] =~ /$START_MARKER/) {
      $start_line = $i;
    } elsif ($lines[$i] =~ /$END_MARKER/) {
      $end_line = $i;
      last;
    }
  }

  die "Marker not found in $MODULE_CONFIG_TEMPLATE:\n$START_MARKER\n" if ($start_line == -1);
  die "Marker not found in $MODULE_CONFIG_TEMPLATE:\n$END_MARKER\n" if ($end_line == -1);

  # Build the mount_entries file
  my @new_file_lines = ();

  # Keep lines before start marker
  for (my $i = 0; $i <= $start_line; $i++) {
    push @new_file_lines, $lines[$i];
  }

  # Add the new mount entries
  foreach my $line (@$new_mount_entries_ref) {
    push @new_file_lines, $line;
  }

  # Keep lines after end marker
  for (my $i = $end_line; $i < @lines; $i++) {
    push @new_file_lines, $lines[$i];
  }

  # Write the generated file
  open(my $write_fh, '>', $MODULE_CONFIG_YAML) or die "Cannot write to $MODULE_CONFIG_YAML: $!\n";
  print $write_fh @new_file_lines;
  close($write_fh);
}

main();
